// Intimate Proximity: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Air: high-shelf boost near 10kHz (g.biquad highshelf) driven by 'air' dB.
//   3. Warmth: low-shelf boost near 250Hz (g.biquad lowshelf) driven by 'warmth' dB.
//   4. Presence: peaking boost near 4kHz (g.biquad peaking) driven by 'presence' dB.
//   5. Dry/wet: g.lerp between the trimmed dry signal and the processed signal by 'dry/wet mix'.
//   6. Output gain: convert 'output gain' dB to linear and scale.
//   7. Bypass: g.lerp(bypass, processed, dry) selects dry vs processed. ASSUMES the 'bypass' enum resolves
//      to 0 ('off') / 1 ('on') and g.lerp(mask,a,b) returns a at mask=0, b at mask=1 (see AUTHORING.md).
//      So bypass 'off' passes the PROCESSED signal and 'on' passes the DRY signal.
//   8. Safety: g.tanh soft-clip before g.output.
// ASSUMPTION: shelf/peaking g.biquad stages pass a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var airDb = g.input('air');
  var warmthDb = g.input('warmth');
  var presenceDb = g.input('presence');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var air = g.biquad({ input: trimmed, cutoff: g.constant(10000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: airDb });
    var warm = g.biquad({ input: air, cutoff: g.constant(250), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: warmthDb });
    var pres = g.biquad({ input: warm, cutoff: g.constant(4000), resonance: g.constant(0.9), mode: 'peaking', gainDb: presenceDb });
    var wet = g.lerp(mix, trimmed, pres);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
